				\begin{document}$$\mathrm{CL}= \left\{\begin{array}{ll}{\mathrm{CL}}_{\mathrm{hep\,}}, & ({f}_{{\mathrm{cl\_}}{\mathrm{h}}}=1)\\ {\mathrm{CL}}_{\mathrm{re\,}}, & ({f}_{{\mathrm{cl\_}}{\mathrm{h}}}=0)\\ {\mathrm{CL}}_{\mathrm{hep}}+ {\mathrm{CL}}_{\mathrm{re}\,}, & ({f}_{{\mathrm{cl\_}}{\mathrm{h}}}=0.5)\end{array}\right.$$\end{document}CL=CLhep,(fcl_h=1)CLre,(fcl_h=0)CLhep+CLre,(fcl_h=0.5)8\documentclass[12pt]{minimal}
